import java.io.*;import java.math.*;import java.security.*;import java.text.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.util.regex.*;import java.util.stream.*;import static java.util.stream.Collectors.joining;import static java.util.stream.Collectors.toList;class Result {public static int pageCount(int n, int p) {int fromFront = p / 2;int fromBack = (n / 2) - (p / 2);return Math.min(fromFront, fromBack);}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));String outputEnv = System.getenv("OUTPUT_PATH");BufferedWriter bufferedWriter = new BufferedWriter(outputEnv != null ? new FileWriter(outputEnv) : new OutputStreamWriter(System.out));int n = Integer.parseInt(bufferedReader.readLine().trim());int p = Integer.parseInt(bufferedReader.readLine().trim());int result = Result.pageCount(n, p);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}